-- Create "video_embeds" table
CREATE TABLE "video_embeds" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "url_hash" character varying NOT NULL, "url" text NOT NULL, "provider" character varying NOT NULL, "title" character varying NOT NULL DEFAULT '', "thumbnail_url" text NOT NULL DEFAULT '', "thumbnail_file" character varying NOT NULL DEFAULT '', "width" bigint NOT NULL DEFAULT 0, "height" bigint NOT NULL DEFAULT 0, "status" character varying NOT NULL DEFAULT 'ok', "fetched_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "video_embeds_url_hash" to table: "video_embeds"
CREATE UNIQUE INDEX "video_embeds_url_hash" ON "video_embeds" ("url_hash");
-- Create "video_embed_settings" table
CREATE TABLE "video_embed_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "providers" character varying NOT NULL DEFAULT '', "click_to_play" boolean NOT NULL DEFAULT true, "local_previews" boolean NOT NULL DEFAULT true, PRIMARY KEY ("id"));
